-- PARTE 3/5 — coleções internas e associações de conceitos às coleções
-- Coleções de origem não fornecem URI própria nos CSV/JSON utilizados.
-- As URIs abaixo são identificadores internos determinísticos do Next Hire, não URIs oficiais da ESCO.
-- Dependências: Partes 1 e 2 já importadas; tabelas e ENUMs previamente criados.
-- researchOccupationsCollection é registrado como coleção, mas a associação com ocupações
-- não pode ser armazenada no schema atual (não existe ocupacao_colecao). Nenhuma relação é inventada.

BEGIN;

-- 1. Metadados das coleções internas
-- Lote 1: 7 coleção(ões)
INSERT INTO esco_dataset.colecao (uri, nome, descricao) VALUES
  ('https://nexthire.local/esco/collection/digital-skills', 'Competências digitais', 'Coleção interna do Next Hire baseada nos conceitos presentes no arquivo ESCO digitalSkillsCollection_pt(2).json. URI interna criada pelo projeto; não é uma URI oficial da ESCO.'),
  ('https://nexthire.local/esco/collection/green-skills', 'Competências verdes', 'Coleção interna do Next Hire baseada nos conceitos presentes no arquivo ESCO greenSkillsCollection_pt.json. URI interna criada pelo projeto; não é uma URI oficial da ESCO.'),
  ('https://nexthire.local/esco/collection/language-skills', 'Competências linguísticas', 'Coleção interna do Next Hire baseada nos conceitos presentes no arquivo ESCO languageSkillsCollection_pt(2).json. URI interna criada pelo projeto; não é uma URI oficial da ESCO.'),
  ('https://nexthire.local/esco/collection/transversal-skills', 'Competências transversais', 'Coleção interna do Next Hire baseada nos conceitos presentes no arquivo ESCO transversalSkillsCollection_pt(2).json. URI interna criada pelo projeto; não é uma URI oficial da ESCO.'),
  ('https://nexthire.local/esco/collection/digcomp-skills', 'Competências DigComp', 'Coleção interna do Next Hire baseada nos conceitos presentes no arquivo ESCO digCompSkillsCollection_pt.json. URI interna criada pelo projeto; não é uma URI oficial da ESCO.'),
  ('https://nexthire.local/esco/collection/research-skills', 'Competências de investigação', 'Coleção interna do Next Hire baseada nos conceitos presentes no arquivo ESCO researchSkillsCollection_pt.json. URI interna criada pelo projeto; não é uma URI oficial da ESCO.'),
  ('https://nexthire.local/esco/collection/research-occupations', 'Ocupações de investigação', 'Coleção interna do Next Hire baseada nos conceitos presentes no arquivo ESCO researchOccupationsCollection_pt.json. URI interna criada pelo projeto; não é uma URI oficial da ESCO.')
ON CONFLICT (uri) DO NOTHING;


