  SELECT COUNT(*) INTO v_missing
  FROM source_uris s
  LEFT JOIN esco_dataset.habilidade h ON h.uri = s.concept_uri
  WHERE h.habilidade_id IS NULL;
  IF v_missing > 0 THEN
    RAISE EXCEPTION 'Parte 3 abortada: % referências de habilidades não encontradas em esco_dataset.habilidade. Execute/verifique a Parte 2.', v_missing;
  END IF;
END;
$validation$;

